function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2400)}
async function copyText(value){try{await navigator.clipboard.writeText(value)}catch{const area=document.createElement('textarea');area.value=value;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();document.execCommand('copy');area.remove()}toast('Скопійовано')}
function profile(){return profiles.find(p=>p.id===activeProfileId)||profiles[0]}
function saveProfiles(){localStorage.setItem(profileKey,JSON.stringify(profiles));localStorage.setItem(activeKey,activeProfileId)}
function normalizeProfiles(){profiles.forEach(p=>{columns.forEach((base,i)=>{let c=p.columns.find(x=>x.key===base.key);if(!c)p.columns.push({...base,order:i});else c.label=base.label});if(!Array.isArray(p.kpis))p.kpis=defaultKpis(p.name)})}
function applyKpiVisibility(){const enabled=new Set(profile().kpis||[]);$$('[data-kpi-card]').forEach(card=>card.hidden=!enabled.has(card.dataset.kpiCard));$('#kpiCards').hidden=!$$('[data-kpi-card]').some(card=>!card.hidden);$('#officerCards').hidden=!enabled.has('officers')}
function displayDate(value){if(!value)return '';const d=new Date(value);return Number.isNaN(d.valueOf())?value:d.toLocaleString('uk-UA',{dateStyle:'short',timeStyle:'short'})}
function displayDateOnly(value){if(!value)return '';const d=new Date(value);return Number.isNaN(d.valueOf())?value:d.toLocaleDateString('uk-UA')}
