async function request(url,options){const r=await fetch(url,options);const body=await r.json();if(!r.ok)throw new Error(body.error||body.message||'Помилка запиту');return body}
function updateMultiSummary(id,placeholder,selection,labelFor=value=>value){const summary=$(`#${id} summary`),values=[...selection];summary.textContent=!values.length?placeholder:values.length===1?labelFor(values[0]):`${placeholder}: ${values.length}`}
function saveFilterState(){localStorage.setItem(filterStateKey,JSON.stringify({search:$('#searchInput').value,dateFrom:$('#dateFromFilter').value,dateTo:$('#dateToFilter').value,officer:officerFilter,sortKey,sortDirection,selections:Object.fromEntries(Object.entries(filterSelections).map(([key,value])=>[key,[...value]]))}))}
function restoreFilterState(){try{const state=JSON.parse(localStorage.getItem(filterStateKey)||'null');if(!state)return;$('#searchInput').value=state.search||'';$('#dateFromFilter').value=state.dateFrom||'';$('#dateToFilter').value=state.dateTo||'';officerFilter=state.officer||'';sortKey=state.sortKey||'receivedDate';sortDirection=state.sortDirection==='asc'?'asc':'desc';Object.entries(state.selections||{}).forEach(([key,values])=>{if(!filterSelections[key]||!Array.isArray(values))return;filterSelections[key].clear();values.forEach(value=>filterSelections[key].add(value))});$$('.multi-filter input[type="checkbox"]').forEach(input=>{input.checked=Object.values(filterSelections).some(selection=>selection.has(input.value))})}catch{localStorage.removeItem(filterStateKey)}}
function renderDynamicFilter(id,items,selection,valueFor,labelFor,placeholder){
  const details=$(`#${id}`),query=details.querySelector('.multi-search').value.trim().toLocaleLowerCase('uk-UA');
  const visible=items.filter(item=>labelFor(item).toLocaleLowerCase('uk-UA').includes(query));
  details.querySelector('.multi-options').innerHTML=visible.map(item=>{const value=valueFor(item);return `<label><input type="checkbox" value="${esc(value)}" ${selection.has(value)?'checked':''}> <span>${esc(labelFor(item))}</span></label>`}).join('')||'<p class="muted">Нічого не знайдено</p>';
  details.querySelectorAll('.multi-options input').forEach(input=>input.onchange=()=>{input.checked?selection.add(input.value):selection.delete(input.value);updateMultiSummary(id,placeholder,selection,value=>{const item=items.find(candidate=>valueFor(candidate)===value);return item?labelFor(item):value});page=1;loadRows()});
  updateMultiSummary(id,placeholder,selection,value=>{const item=items.find(candidate=>valueFor(candidate)===value);return item?labelFor(item):value});
}
async function loadFrameworks(){
  try {
    const data=await request(`${API}/frameworks`);
    frameworkOptions=data.items;
    renderDynamicFilter('frameworkFilter',frameworkOptions,filterSelections.framework,item=>item.id,item=>`${item.pretty_id} · ${item.title||''} · ${item.applications_count}`,'Усі відбори');
    const dkOptions=[...new Set(frameworkOptions.map(item=>item.dk_code).filter(Boolean))].sort().map(code=>({code}));
    const supplierDkOptions=$('#supplierRegistryDkOptions');
    if(supplierDkOptions)supplierDkOptions.innerHTML=dkOptions.map(item=>`<option value="${esc(item.code)}"></option>`).join('');
    renderDynamicFilter('dkFilter',dkOptions,filterSelections.dk,item=>item.code,item=>item.code,'Усі коди ДК');
  } catch(e) { toast(e.message) }
}
async function loadSupplierOptions(){try{const q=new URLSearchParams({search:$('#supplierCodeFilter .multi-search').value});const data=await request(`${API}/supplier-options?${q}`);renderDynamicFilter('supplierCodeFilter',data.items,filterSelections.supplier,item=>item.code,item=>`${item.code} · ${item.name||''} (${item.applications_count})`,'Коди ЄДРПОУ')}catch(e){toast(e.message)}}
function currentFilterParams(){return {search:$('#searchInput').value,status:[...filterSelections.status].join(','),registry_status:[...filterSelections.registry].join(','),supplier_codes:[...filterSelections.supplier].join(','),framework_id:[...filterSelections.framework].join(','),dk_code:[...filterSelections.dk].join(','),date_from:$('#dateFromFilter').value,date_to:$('#dateToFilter').value,officer:officerFilter}}
async function loadStats(){const q=new URLSearchParams(currentFilterParams()),signature=q.toString();if(signature===statsSignature)return;statsSignature=signature;try{const data=await request(`${API}/stats?${q}`);$$('[data-kpi]').forEach(el=>el.textContent=Number(data[el.dataset.kpi]||0).toLocaleString('uk-UA'));$('#officerCards').innerHTML=(data.officers||[]).map(item=>`<button type="button" class="officer-card ${item.officer==='Не визначено'?'unassigned':''} ${item.officer===officerFilter?'active':''}" data-officer="${esc(item.officer)}"><span title="${esc(item.officer)}">${esc(item.officer)}</span><strong>${Number(item.applications||0).toLocaleString('uk-UA')}</strong></button>`).join('');$$('#officerCards [data-officer]').forEach(card=>card.onclick=()=>{officerFilter=officerFilter===card.dataset.officer?'':card.dataset.officer;page=1;statsSignature='';loadRows()})}catch(e){statsSignature='';toast(e.message)}}
async function loadRows(){
  const generation=++loadRowsGeneration;
  saveFilterState();loading=true;render();
  try{
    const q=new URLSearchParams({...currentFilterParams(),page,size:'50',sort:sortKey,direction:sortDirection});
    const [data]=await Promise.all([request(`${API}/applications?${q}`),loadStats()]);
    if(generation!==loadRowsGeneration)return;
    rows=data.items.map(mapRow);page=data.page;pages=data.pages||1;total=data.total;selected.clear();
  }catch(e){
    if(generation===loadRowsGeneration){rows=[];total=0;pages=1;selected.clear();toast(`Не вдалося застосувати фільтр: ${e.message}`)}
  }finally{
    if(generation===loadRowsGeneration){loading=false;render()}
  }
}
function bindStaticMulti(id,selection,placeholder){const details=$(`#${id}`);details.onchange=e=>{if(!e.target.matches('input[type="checkbox"]'))return;e.target.checked?selection.add(e.target.value):selection.delete(e.target.value);updateMultiSummary(id,placeholder,selection);page=1;loadRows()};updateMultiSummary(id,placeholder,selection)}
function getCols(){return [...profile().columns].filter(c=>c.visible).sort((a,b)=>a.order-b.order)}
function syncTableScroll(){const top=$('#tableScrollTop'),bottom=$('#tableScroll'),spacer=top.firstElementChild;spacer.style.width=`${bottom.scrollWidth}px`;if(top.dataset.bound)return;top.dataset.bound='true';top.onscroll=()=>{if(bottom.scrollLeft!==top.scrollLeft)bottom.scrollLeft=top.scrollLeft};bottom.onscroll=()=>{if(top.scrollLeft!==bottom.scrollLeft)top.scrollLeft=bottom.scrollLeft}}
