  if(col.key==='clarity')return `<td class="${sticky} link-cell">${row.edrpou?`<a class="external-link clarity-link" href="https://clarity-project.info/edr/${encodeURIComponent(row.edrpou)}" target="_blank" rel="noopener" title="Відкрити в Clarity Project" aria-label="Clarity Project">CP</a>`:'<span class="muted">—</span>'}</td>`;
  if(col.key==='marketplaceLink'||col.key==='prozorroLink'){const url=row[col.key],label=col.key==='marketplaceLink'?'Відкрити на майданчику':'Відкрити в Prozorro';return `<td class="${sticky} link-cell">${url?`<a class="external-link" href="${esc(url)}" target="_blank" rel="noopener" title="${label}" aria-label="${label}">&#128279;</a>`:'<span class="muted">—</span>'}</td>`}
  if(col.key==='documents')return `<td class="${sticky}"><button class="paperclip" title="Відкрити документи">📎 <span>${row.documents.length}</span></button></td>`;
  if(col.key==='registryDocuments')return `<td class="${sticky}"><button class="registry-paperclip paperclip" title="Відкрити документи реєстру" ${row.registryDocuments.length?'':'disabled'}>📎 <span>${row.registryDocuments.length}</span></button></td>`;
  if(col.key==='documentCheckStatus'){const c=row.documentCheckStatus==='ok'?'admit':row.documentCheckStatus==='error'?'reject':'wait',summary=row.documentCheckSummary||'Не перевірено — натисніть, щоб виконати першу перевірку';return `<td class="${sticky}"><button class="check-result-card ${c}" title="Відкрити збережений результат перевірки"><strong>${esc(summary)}</strong><small>${row.documentCheckedAt?`Станом на ${esc(row.documentCheckedAt)}`:'Результату ще немає'}</small></button></td>`}
  if(col.key==='managerName'&&row.managerNameSource==='previous_application'){const isLocked=locked(row,col.key);return `<td class="${sticky} auto-filled ${isLocked?'locked':'cell-editable'}" data-key="${isLocked?'':'managerName'}" title="Автоматично перенесено з останньої попередньої заявки цього ЄДРПОУ. Перевірте значення.">${esc(row.managerName)}</td>`}
  if(col.key==='decision'){const c=row.decision==='Допущено'?'admit':row.decision==='Відхилено'?'reject':'wait';return `<td class="${sticky}"><span class="status ${c}">${row.decision}</span></td>`}
  if(col.key==='registryStatus'){if(!row.registryStatus)return `<td class="${sticky}"><span class="muted">—</span></td>`;const c=row.registryStatus==='Активний'?'admit':row.registryStatus.startsWith('Неактивний')?'reject':'wait';return `<td class="${sticky}"><span class="status ${c}">${esc(row.registryStatus)}</span></td>`}
  if(col.key==='protocolDecision'){const label=protocolDecisions.find(([value])=>value===row.protocolDecision)?.[1]||'Не визначено',c=row.protocolDecision==='admit'?'admit':row.protocolDecision==='reject'?'reject':'wait',actionLocked=Boolean(row.marketplaceDecision),isLocked=locked(row,col.key)||actionLocked,title=actionLocked?'Щоб змінити Рішення УО, спочатку скиньте дію на майданчику':'';return `<td class="${sticky} ${isLocked?'locked':'cell-editable'}" data-key="${isLocked?'':'protocolDecision'}" title="${title}"><span class="status ${c}">${label}</span></td>`}
  if(col.key==='marketplaceDecision'){const label=marketplaceDecisions.find(([value])=>value===row.marketplaceDecision)?.[1]||'Не виконано',c=row.marketplaceDecision==='admit'?'admit':row.marketplaceDecision==='reject'?'reject':'wait',rowLocked=locked(row,col.key),missing=[];if(!row.protocolDecision)missing.push('Рішення УО');if(!row.managerName)missing.push('ПІБ керівника');if(!row.protocolNumber)missing.push('№ протоколу');if(!row.protocolDate)missing.push('дату протоколу');if(row.complianceStatus==='rejected'&&!row.complianceComments)missing.push('коментар комплаєнс');const formed=Boolean(row.protocolGeneratedAt)&&row.generatedProtocolNumber===row.protocolNumber&&row.generatedProtocolDate===row.protocolDate&&row.generatedProtocolDecision===row.protocolDecision;if(!formed)missing.push('сформований протокол із поточними даними');const isLocked=rowLocked||missing.length>0,title=rowLocked&&row.marketplaceDecision?'Рядок заблоковано виконаною дією на майданчику':missing.length?`Недоступно: ${missing.join(', ')}`:'';return `<td class="${sticky} ${isLocked?'locked':'cell-editable'}" data-key="${isLocked?'':'marketplaceDecision'}" title="${title}"><span class="status ${c}">${label}</span></td>`}
