async function saveField(row,key,value){await request(`${API}/applications/${row.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({[fieldMap[key]]:value})})}
function buildRemarksText(){
  if(document.querySelector('input[name="remarksMode"]:checked')?.value==='none')return 'Без зауважень';
  const chosen=remarksItems.filter(item=>remarksSelected.has(String(item.id)));if(!chosen.length)return '';
  const points=[];chosen.forEach(item=>{if(!points.includes(item.point))points.push(item.point)});
  const bodies=chosen.map(item=>item.text.trim().replace(/[.;]+$/,'')).filter(Boolean);
  return `Не виконано вимоги ${points.join(', ')} «Кваліфікаційних та інших вимог до учасника» (${bodies.join('; ')}).`;
}
function renderRemarksCatalog(){
  const query=$('#remarksSearch').value.trim().toLocaleLowerCase('uk-UA');
  const shown=remarksItems.filter(item=>!query||`${item.point} ${item.text} ${item.tag} ${item.category}`.toLocaleLowerCase('uk-UA').includes(query));
  $('#remarksCatalog').innerHTML=shown.length?shown.map(item=>`<label class="remark-option"><input type="checkbox" value="${esc(item.id)}" ${remarksSelected.has(String(item.id))?'checked':''}><strong>${esc(item.point)}</strong><span>${esc(item.text)}${item.category||item.tag?`<small>${esc([item.category,item.tag].filter(Boolean).join(' · '))}</small>`:''}</span><span class="remark-actions"><button type="button" class="remark-edit" data-id="${esc(item.id)}" title="Редагувати шаблон">✎</button><button type="button" class="remark-disable" data-id="${esc(item.id)}" title="Прибрати з довідника">×</button></span></label>`).join(''):'<p class="muted" style="padding:16px">Варіантів не знайдено</p>';
  $$('#remarksCatalog input[type="checkbox"]').forEach(input=>input.onchange=()=>{input.checked?remarksSelected.add(input.value):remarksSelected.delete(input.value);document.querySelector('input[name="remarksMode"][value="selected"]').checked=true;$('#remarksPicker').hidden=false;$('#remarksPreview').value=buildRemarksText()});
}
