async function checkProtocol(e){e.preventDefault();try{const payload={protocol_number:$('#checkProtocolNumber').value.trim(),date_from:$('#checkDateFrom').value,date_to:$('#checkDateTo').value,filters:currentFilterParams()};const data=await request(`${API}/protocol/readiness`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});lastProtocolPayload=data.ready?payload:null;const summary=$('#protocolSummary');summary.className=`protocol-summary ${data.ready?'ready':'blocked'}`;summary.textContent=data.ready?`Перевірку пройдено: ${data.total} заявок · Рішення УО «Так» — ${data.admitted} · «Ні» — ${data.rejected}${data.warning_count?` · попереджень ${data.warning_count}`:''}`:`Не готово: ${data.total} заявок · Рішення УО не визначено — ${data.unresolved} · помилок ${data.error_count}`;const issues=data.items.filter(item=>item.errors.length||item.warnings.length);$('#protocolIssues').innerHTML=issues.map(item=>`<div class="protocol-issue"><strong>${esc(item.supplier_name)} · ${esc(item.supplier_code)} · ${esc(item.pretty_id)}</strong>${item.errors.map(error=>`<span>${esc(error)}</span>`).join('')}${item.warnings.map(warning=>`<span class="muted">${esc(warning)}</span>`).join('')}</div>`).join('')||(data.ready?'<p class="muted">Контрольних зауважень немає. Протокол можна формувати.</p>':'<p class="muted">Заявок для протоколу не знайдено.</p>');$('#generateProtocolBtn').disabled=!data.ready}catch(error){lastProtocolPayload=null;$('#generateProtocolBtn').disabled=true;toast(error.message)}}
async function generateProtocol(){if(!lastProtocolPayload)return;const button=$('#generateProtocolBtn'),old=button.textContent;button.disabled=true;button.textContent='Формування…';try{const data=await request(`${API}/protocol/generate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(lastProtocolPayload)});const link=document.createElement('a');link.href=data.download_url;link.download=data.filename;document.body.appendChild(link);link.click();link.remove();$('#protocolSummary').className='protocol-summary ready';$('#protocolSummary').textContent=`Протокол № ${data.protocol_number} сформовано: ${data.total} заявок · допущено ${data.admitted} · відхилено ${data.rejected}`;toast('Протокол сформовано та завантажено');await loadRows()}catch(error){toast(error.message);button.disabled=false}finally{button.textContent=old}}
function openBulk(){
  const labels={protocolNumber:'Номер протоколу',protocolDate:'Дата протоколу',publicationDate:'Дата публікації рішення',protocolOfficer:'УО протоколу',protocolDecision:'Рішення УО',complianceStatus:'Комплаєнс',complianceComments:'Коментарі комплаєнс',protocolRemarks:'Зауваження до протоколу',managerName:'Прізвище, ім’я, по батькові керівника',documentPackage:'Пакет документів'};
  const control=key=>key==='protocolOfficer'?`<select data-bulk="${key}" disabled><option value="">Не вибрано</option>${protocolOfficers.map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join('')}</select>`:key==='protocolDecision'?`<select data-bulk="${key}" disabled>${protocolDecisions.map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select>`:key==='complianceStatus'?`<select data-bulk="${key}" disabled>${complianceStatuses.map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select>`:`<input data-bulk="${key}" disabled>`;
  $('#bulkFields').innerHTML=Object.keys(labels).map(key=>`<div class="form-field"><div class="field-enable"><input type="checkbox" data-enable="${key}"><label>${labels[key]}</label></div>${control(key)}</div>`).join('');
  $$('[data-enable]').forEach(item=>item.onchange=()=>{$(`[data-bulk="${item.dataset.enable}"]`).disabled=!item.checked});
  $('#bulkDialog').showModal();
}
async function applyBulk(e){e.preventDefault();const changes={};$$('[data-enable]:checked').forEach(x=>changes[fieldMap[x.dataset.enable]]=$(`[data-bulk="${x.dataset.enable}"]`).value.trim());if(!Object.keys(changes).length)return toast('Оберіть поля');const chosen=rows.filter(row=>selected.has(row.id));const missingCompliance=chosen.some(row=>(changes.protocol_decision??row.protocolDecision)&&!(changes.compliance_status??row.complianceStatus));if(missingCompliance)return toast('Спочатку визначте рішення комплаєнс');const changesLockedCompliance=Object.hasOwn(changes,'compliance_status')&&chosen.some(row=>changes.compliance_status!==row.complianceStatus&&row.protocolDecision);if(changesLockedCompliance)return toast('Щоб змінити комплаєнс, спочатку встановіть Рішення УО «Не визначено»');const conflict=chosen.some(row=>(changes.protocol_decision??row.protocolDecision)==='admit'&&(changes.compliance_status??row.complianceStatus)==='rejected');if(conflict)return toast('Рішення УО «Так» неможливе, коли комплаєнс не погоджено');try{await Promise.all([...selected].map(id=>request(`${API}/applications/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(changes)})));$('#bulkDialog').close();selected.clear();await loadRows();toast('Масові зміни застосовано')}catch(e2){toast(e2.message)}}
