async function loadViolationReports(){const body=$('#requestsBody');body.innerHTML='<tr><td colspan="10">Завантаження…</td></tr>';try{const q=new URLSearchParams({search:$('#requestsSearch').value.trim(),status:$('#requestsStatus').value,reason:$('#requestsReason').value,authority_code:selectedRequestAuthority,date_from:$('#requestsDateFrom').value,date_to:$('#requestsDateTo').value,page:String(requestsPage),size:'100'});const data=await request(`${API}/violation-reports?${q}`);requestsPages=Math.max(1,Number(data.pages||1));if(requestsPage>requestsPages){requestsPage=requestsPages;return loadViolationReports()}violationReports=data.items||[];$('#requestsTotal').textContent=Number(data.total||0).toLocaleString('uk-UA');$('#requestsSatisfied').textContent=Number(data.satisfied||0).toLocaleString('uk-UA');populateRequestSelect('#requestsStatus',data.statuses,requestStatusLabels,'Усі статуси');populateRequestSelect('#requestsReason',data.reasons,requestReasonLabels,'Усі підстави');renderRequestAuthorityCards(data.authorities);const sync=data.sync||{};$('#requestsRefresh').disabled=Boolean(sync.running);$('#requestsSyncStatus').textContent=sync.running?(sync.message||'Синхронізація триває…'):(sync.updated_at?`${sync.message} · ${displayDate(sync.updated_at)}`:'Натисніть «Оновити з Prozorro», щоб завантажити офіційний реєстр');body.innerHTML=violationReports.length?violationReports.map((item,index)=>{const deadline=requestDeadline(item),statements=item.defendant_statements||[];return`<tr class="request-row" data-request-index="${index}"><td><strong>${esc(item.report_id||item.id)}</strong></td><td>${esc(displayDate(item.date_published))}</td><td><strong>${esc(item.author_name)||'—'}</strong><small>${esc(item.author_code)}</small></td><td><strong>${esc(item.defendant_name)||'—'}</strong><small>${esc(item.defendant_code)}</small></td><td>${esc(requestLabel(item.reason,requestReasonLabels))}</td><td>${deadline.html}${statements.length?`<small class="statement-received">Пояснення надано: ${statements.length}</small>`:''}</td><td>${requestTenderLinks(item)}</td><td><span class="request-status status-${esc(item.status)}">${esc(requestLabel(item.status,requestStatusLabels))}</span></td><td>${esc(requestLabel(item.decision_resolution,requestStatusLabels))}</td><td>${Number((item.evidence_documents||[]).length)+Number((item.decision_documents||[]).length)+statements.reduce((n,s)=>n+(s.documents||[]).length,0)}</td></tr>`}).join(''):'<tr><td colspan="10">Звернень за вибраними умовами не знайдено</td></tr>';const total=Number(data.total||0),from=total?(requestsPage-1)*100+1:0,to=Math.min(requestsPage*100,total);$('#requestsPageInfo').textContent=`Показано ${from}–${to} із ${total.toLocaleString('uk-UA')} звернень · сторінка ${requestsPage} із ${requestsPages}`;$('#requestsPrev').disabled=requestsPage<=1;$('#requestsNext').disabled=requestsPage>=requestsPages;if(sync.running&&!requestsPolling)requestsPolling=setInterval(async()=>{await loadViolationReports();const state=(await request(`${API}/violation-reports?size=10`)).sync;if(!state.running){clearInterval(requestsPolling);requestsPolling=null}},2500)}catch(error){body.innerHTML=`<tr><td colspan="10">${esc(error.message)}</td></tr>`}}
