  if(['active','активне','активний','активна'].includes(key))return{key:'active',label:'Активний'};
  if(['closed','complete','inactive','disabled','закрите','закритий','закрито','неактивне','неактивний'].includes(key))return{key:'closed',label:'Закритий'};
