async function loadBidsSyncStatus(){const button=$('#bidsStatusRefresh');button.disabled=true;$('#bidsSyncHeadline').textContent='Читання великої бази…';try{const data=await request(`${API}/bids-sync-status?t=${Date.now()}`),number=value=>Number(value||0).toLocaleString('uk-UA'),date=value=>value?displayDate(value):'—',dateOnly=value=>value?displayDateOnly(value):'—';$('#bidsAgreements').textContent=number(data.agreements);$('#bidsAgreementsDetail').textContent=`Перевірено: ${number(data.searched_agreements)}`;$('#bidsTenders').textContent=number(data.tenders);$('#bidsTendersDetail').textContent=`Деталізовано: ${number(data.detailed_tenders)}`;$('#bidsCount').textContent=number(data.bids);$('#bidsAwards').textContent=number(data.awards);$('#bidsPending').textContent=number(data.pending_tenders);$('#bidsErrors').textContent=`Помилки: ${number(Number(data.tender_errors||0)+Number(data.agreement_errors||0))}`;$('#bidsCoverage').textContent=`${dateOnly(data.tender_from)} — ${dateOnly(data.tender_to)}`;$('#bidsModifiedTo').textContent=dateOnly(data.modified_to);$('#bidsLastSearch').textContent=date(data.last_search_at);$('#bidsLastDetail').textContent=date(data.last_detail_at);const run=data.last_completed;$('#bidsLastRun').textContent=run?`${date(run.finished_at)} · ${run.mode} · деталізовано ${number(run.details_loaded)}`:'Немає завершених запусків';$('#bidsDatabase').textContent=data.database||'—';$('#bidsSyncBadge').textContent=data.history_complete?'Історію завершено':'Є черга';$('#bidsSyncBadge').className=`bids-sync-badge ${data.history_complete?'complete':'pending'}`;$('#bidsSyncHeadline').textContent=data.history_complete?'Усі знайдені закупівлі деталізовано':'Частина закупівель очікує деталізації';const warning=$('#bidsSyncWarning'),stale=data.stale_open_logs||[];warning.hidden=!stale.length;warning.textContent=stale.length?`У журналі залишилось незакритих старих запусків: ${stale.length}. Вони не активні, оскільки черга деталізації порожня.`:''}catch(error){$('#bidsSyncHeadline').textContent=error.message;$('#bidsSyncBadge').textContent='Помилка';$('#bidsSyncBadge').className='bids-sync-badge error'}finally{button.disabled=false}}
