async function startBidsUpdate(){try{$('#bidsDataRefresh').disabled=true;await request(`${API}/bids-sync`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});$('#bidsSyncHeadline').textContent='Оновлення Bids запущено…';clearInterval(bidsUpdateTimer);bidsUpdateTimer=setInterval(async()=>{try{const data=await request(`${API}/bids-sync-status?t=${Date.now()}`),state=data.update||{};$('#bidsSyncHeadline').textContent=state.message||'Оновлення триває…';if(!state.running){clearInterval(bidsUpdateTimer);bidsUpdateTimer=null;$('#bidsDataRefresh').disabled=false;await loadBidsSyncStatus();toast(state.error?'Оновлення Bids завершилося з помилкою':'Дані Bids оновлено')}}catch(error){clearInterval(bidsUpdateTimer);bidsUpdateTimer=null;$('#bidsDataRefresh').disabled=false;toast(error.message)}},4000)}catch(error){$('#bidsDataRefresh').disabled=false;toast(error.message)}}
