async function loadPowerbiStatus(){try{const data=await request(`${API}/powerbi-export-status?t=${Date.now()}`),state=data.state||{},mb=Number(data.size_bytes||0)/1048576;$('#powerbiPath').textContent=data.path||'—';$('#powerbiUpdated').textContent=data.updated_at?displayDate(data.updated_at):'Ще не створено';$('#powerbiSize').textContent=data.exists?(mb>=1024?(mb/1024).toLocaleString('uk-UA',{maximumFractionDigits:2})+' ГБ':mb.toLocaleString('uk-UA',{maximumFractionDigits:0})+' МБ'):'—';$('#powerbiRows').textContent=Number(data.total_rows||0).toLocaleString('uk-UA');$('#powerbiDatasets').innerHTML=(data.datasets||[]).map(item=>`<span><strong>${esc(item.name)}</strong>${Number(item.rows||0).toLocaleString('uk-UA')} рядків · ${Number(item.files||0)} файлів</span>`).join('');$('#powerbiStatusMessage').textContent=state.running?state.message:(state.error?state.message:(data.complete?'Набір готовий до оновлення в Power BI.':'Постійний набір ще не створено.'));$('#powerbiExportBtn').disabled=Boolean(state.running);return state}catch(error){$('#powerbiStatusMessage').textContent=error.message;return{}}}
async function startPowerbiExport(){try{$('#powerbiExportBtn').disabled=true;await request(`${API}/powerbi-export`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});$('#powerbiStatusMessage').textContent='Експорт запущено. Чинний набір залишається доступним до завершення.';clearInterval(powerbiPollTimer);powerbiPollTimer=setInterval(async()=>{const state=await loadPowerbiStatus();if(!state.running){clearInterval(powerbiPollTimer);powerbiPollTimer=null;toast(state.error?'Експорт Power BI завершився з помилкою':'Базу Power BI оновлено')}},4000)}catch(error){$('#powerbiExportBtn').disabled=false;toast(error.message)}}
